(function(root){
 function extent(values){const numbers=values.filter(Number.isFinite);if(!numbers.length)return[0,100];let min=numbers.reduce((a,b)=>Math.min(a,b)),max=numbers.reduce((a,b)=>Math.max(a,b));const padding=max===min?Math.max(Math.abs(max)*.05,100):(max-min)*.08;return[min-padding,max+padding];}
 function scale(values,window=null,zero=false){let [min,max]=window||extent(values);if(zero&&!window)min=Math.min(0,min);if(!Number.isFinite(min)||!Number.isFinite(max)||max<=min)throw Error('纵轴上限必须大于下限。');const base=10**Math.floor(Math.log10((max-min)/4)),step=([1,2,2.5,5,10].find(n=>n>=(max-min)/4/base)||10)*base;if(!window){min=Math.floor(min/step)*step;max=Math.ceil(max/step)*step;if(values.every(v=>v===null||v>=0))min=Math.max(0,min);}const ticks=[];for(let v=Math.ceil(min/step)*step;v<=max+step*1e-8&&ticks.length<20;v+=step)ticks.push(v);if(!ticks.length||Math.abs(ticks[0]-min)>step*1e-8){if(ticks.length&&ticks[0]-min<step*.35)ticks.shift();ticks.unshift(min);}return{min,max,step,ticks};}
 function zoom(bounds,factor){const center=(bounds.min+bounds.max)/2,span=Math.max(2,(bounds.max-bounds.min)*factor);return[center-span/2,center+span/2];}
 function memberColor(profile,index){return /^#[0-9a-f]{6}$/i.test(profile?.color||'')?profile.color:profile?.gender==='male'?'#168bd2':profile?.gender==='female'?'#df5987':['#279bb4','#df718e','#c28b2d','#56a16c','#7382d5'][Math.max(index,0)%5];}
 const yearPalette=['#6750d8','#e28024','#119a83','#d64d82','#288bc5','#9b62b5','#788b25','#b55735'];
 function yearColor(year){return'hsl('+(((Number(year)-2000)*137.508%360+360)%360).toFixed(2)+' 67% 48%)';}
 const api={extent,scale,zoom,memberColor,yearColor};if(typeof module!=='undefined'&&module.exports){module.exports=api;return;}root.FamilyChartAxis=api;
 api.attach=function(parent,label,onChange){let zero=true;const panel=document.createElement('div');panel.className='y-axis-controls';panel.innerHTML='<div class="y-axis-buttons"><strong>金额起点</strong></div>';const group=panel.firstChild,buttons=[];
 for(const [text,value]of [['纵轴从0开始',true],['从当前数据的最小值开始',false]]){const b=document.createElement('button');b.type='button';b.className='outline';b.textContent=text;b.onclick=()=>{zero=value;update();onChange();};buttons.push([b,value]);group.append(b);}function update(){for(const [b,value]of buttons){b.classList.toggle('active',value===zero);b.setAttribute('aria-pressed',String(value===zero));}}update();parent.append(panel);
 return{scale(values){const finite=values.filter(Number.isFinite);if(!finite.length)return scale([]);const min=zero?finite.reduce((a,b)=>Math.min(a,b),0):finite.reduce((a,b)=>Math.min(a,b)),max=finite.reduce((a,b)=>Math.max(a,b));return scale(values,[min,max+Math.max((max-min)*.08,Math.abs(max)*.01,1)]);},reset(){update();}};
 };
})(typeof globalThis!=='undefined'?globalThis:this);
